function smallestFactorization(num) {
  // Try every non-decreasing list of digits 2..9 whose product is num; keep the shortest, then the smallest.
  if (num === 1) return 1;
  let best = null;
  const search = (rest, low, digits) => {
    if (rest === 1) {
      const text = digits.join('');
      if (best === null || text.length < best.length || (text.length === best.length && text < best)) best = text;
      return;
    }
    if (best !== null && digits.length >= best.length) return;
    for (let d = low; d <= 9; d++) {
      if (rest % d === 0) { digits.push(d); search(rest / d, d, digits); digits.pop(); }
    }
  };
  search(num, 2, []);
  if (best === null || best.length > 10 || Number(best) > 2147483647) return 0;
  return Number(best);
}

