  let num = 1;
  const count = size === 'large' ? 10 + Math.floor(rand() * 20) : Math.floor(rand() * 12);
  for (let k = 0; k < count; k++) {
    const d = 2 + Math.floor(rand() * 8);
    if (num * d > LIMIT) break;
    num *= d;
  }
  const prime = [11, 13, 17][Math.floor(rand() * 3)];
  if (rand() < 0.15 && num * prime <= LIMIT) num *= prime;
